pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // setup: caller must be the from address
        address sender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        address recipient = address(0x1234);
        // construct arrays for a single recipient with a non-zero value
        address[] memory tos = new address[](1);
        tos[0] = recipient;
        uint[] memory vals = new uint[](1);
        vals[0] = 1; // 1 wei * 1e18 = 1e18, passes the safe multiplication check

        // execute the call as the allowed sender
        vm.prank(sender);
        c.transfer(tos, vals);

        // After a call, the reference keeps `from` and `caddress` unchanged.
        // The buggy delegatecall changes them because the called contract's storage is overwritten.
        // In the reference, from remains as originally set.
        assertTrue(c.from() == sender);
    }
}

