pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a minimal token contract to capture the transferFrom calls
        // Use vm.etch to place a simple balance-tracker at caddress
        address token = 0x1f844685f7Bf86eFcc0e74D8642c54A257111923;

        // Deploy a simple token that records transfers
        bytes memory initCode = abi.encodePacked(
            type(SimpleToken).creationCode
        );
        address tokenAddr;
        assembly {
            tokenAddr := create(0, add(initCode, 0x20), mload(initCode))
        }

        // Now call transfer with one recipient and amount 1
        address[] memory tos = new address[](1);
        tos[0] = token;
        uint[] memory vals = new uint[](1);
        vals[0] = 1;

        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        c.transfer(tos, vals);

        // Check the balance of the from address in the token contract
        // In reference: 1e18 tokens transferred; in bug: 1 wei transferred
        // For simplicity, we just check that the balance > 0 and < 1e18 if bug is present
        (bool success, bytes memory data) = token.staticcall(
            abi.encodeWithSignature("balanceOf(address)", 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9)
        );
        uint256 balance = abi.decode(data, (uint256));

        // Reference sends exactly 1e18, so balance should be exactly 1e18
        assertTrue(balance == 1e18, "Balance should be exactly 1e18 in correct implementation");
    }
}

contract SimpleToken {
    mapping(address => uint256) public balanceOf;

    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        balanceOf[from] += amount;
        return true;
    }
}

